import{_ as d,C as r,o as s,c as g,j as n,a as t,E as o,a2 as a}from"./chunks/framework.CtQGab4e.js";const f=JSON.parse('{"title":"Gebouweigenschappen","description":"","frontmatter":{},"headers":[],"relativePath":"plattegrond/gebouw.md","filePath":"plattegrond/gebouw.md"}'),p={name:"plattegrond/gebouw.md"};function h(u,e,v,k,b,m){const i=r("Icon"),l=r("Media");return s(),g("div",null,[e[12]||(e[12]=n("h1",{id:"gebouweigenschappen",tabindex:"-1"},[t("Gebouweigenschappen "),n("a",{class:"header-anchor",href:"#gebouweigenschappen","aria-label":'Permalink to "Gebouweigenschappen"'},"​")],-1)),n("p",null,[e[0]||(e[0]=t("Open ",-1)),o(i,{name:"building"}),e[1]||(e[1]=t()),e[2]||(e[2]=n("strong",null,"Eigenschappen",-1)),e[3]||(e[3]=t(". Hier staat wat voor het hele gebouw geldt: de oriëntatie, de hoogtes, hoe de verdiepingen op elkaar liggen en de isolaties. De 3D-server heeft dit nodig.",-1))]),o(l,{src:"gebouw-sidebar.png",width:"320"}),e[13]||(e[13]=a('<h2 id="orientatie" tabindex="-1">Oriëntatie <a class="header-anchor" href="#orientatie" aria-label="Permalink to &quot;Oriëntatie&quot;">​</a></h2><p>Twee wieltjes:</p><ul><li><strong>Oriëntatie</strong>: waar het noorden is ten opzichte van je tekening.</li><li><strong>Voorgevel</strong>: welke kant van je tekening de voorgevel is. Standaard is dat de onderkant.</li></ul><p>De 3D-server gebruikt dit om de oppervlaktes per windrichting te geven.</p><p>Klopt de oriëntatie, vink dan <strong>Oriëntatie bevestigd</strong> aan. Zonder dat vinkje kun je niet <a href="./export-3d.html">exporteren</a>; genereren kan wel. Draai je aan het wieltje <strong>Oriëntatie</strong>, dan gaat het vinkje vanzelf aan. Bij het wieltje <strong>Voorgevel</strong> niet.</p><h2 id="hoogtes" tabindex="-1">Hoogtes <a class="header-anchor" href="#hoogtes" aria-label="Permalink to &quot;Hoogtes&quot;">​</a></h2><p>Per verdieping vul je de <strong>hoogte</strong> in meters in, van vloer tot vloer. Leeg = deze verdieping bestaat niet.</p><p class="opmerking">* Het veld naast de hoogte is een opmerking voor jezelf, bijvoorbeeld <em>incl. vloer</em>.</p><h3 id="de-bovenste-verdieping" tabindex="-1">De bovenste verdieping <a class="header-anchor" href="#de-bovenste-verdieping" aria-label="Permalink to &quot;De bovenste verdieping&quot;">​</a></h3><ul><li><strong>Onder een plat dak</strong>: vul de hoogte tot het platte dak in. Die hoogte bepaalt waar het dak komt.</li><li><strong>Onder een hellend dak</strong>: vul de gemeten nokhoogte in. Die is alleen een indicatie: de 3D-server rekent de nok zelf uit uit de goothoogte en de helling van de gevels.</li></ul><h3 id="gebouwdelen" tabindex="-1">Gebouwdelen <a class="header-anchor" href="#gebouwdelen" aria-label="Permalink to &quot;Gebouwdelen&quot;">​</a></h3><p>Heeft een aanbouw of achterhuis andere verdiepingshoogtes dan het hoofdhuis, dan maak je er een <strong>gebouwdeel</strong> van: een eigen tabblad boven de hoogtes, naast <em>Hoofdhuis</em>.</p>',12)),n("ul",null,[e[11]||(e[11]=a('<li><strong>Toevoegen</strong>: tik op <strong>+</strong> naast de tabbladen en geef een naam, bijvoorbeeld <em>Aanbouw</em>. De naam komt terug in de constructies, ook in <a href="./label-wise.html#wat-het-bestand-doet">Label-wise</a>.</li><li><strong>Hoogtes</strong>: vul per verdieping de hoogte van dít gebouwdeel in. Leeg = dit gebouwdeel bestaat niet op die verdieping.</li><li><strong>Vloer boven maaiveld</strong>: ligt dit gebouwdeel in zijn geheel hoger, bijvoorbeeld een voorhuis met een opstapje vanuit het achterhuis, vul dan in hoeveel. Het laagste gebouwdeel is 0. Zweeft het deel, zoals een erker, zet dan de <a href="./vlakken.html#vloerbegrenzing">vloerbegrenzing</a> op <strong>Buiten</strong>.</li>',3)),n("li",null,[e[4]||(e[4]=n("strong",null,"Toewijzen",-1)),e[5]||(e[5]=t(": tik met de ",-1)),o(i,{name:"wall"}),e[6]||(e[6]=t()),e[7]||(e[7]=n("strong",null,"Muur",-1)),e[8]||(e[8]=t("-tool in een ruimte en kies het gebouwdeel in de ",-1)),e[9]||(e[9]=n("a",{href:"./vlakken.html#gebouwdeel"},"vlak-popup",-1)),e[10]||(e[10]=t(".",-1))])]),e[14]||(e[14]=a('<div class="tip custom-block"><p class="custom-block-title">Alleen een lager plat dak?</p><p>Dan kan het ook zonder gebouwdeel: vul de hoogte in bij het platte dak in de vlak-popup. Het verschil zit in de uitkomst, zie <a href="./../hoe-teken-ik/aanbouw.html">Gebouwdeel of plat dak met een eigen hoogte?</a>.</p></div><p>Stappenplan: <a href="./../hoe-teken-ik/aanbouw.html">Aanbouw met eigen hoogtes</a>.</p><h2 id="referentiepunten" tabindex="-1">Referentiepunten <a class="header-anchor" href="#referentiepunten" aria-label="Permalink to &quot;Referentiepunten&quot;">​</a></h2><p>Alle verdiepingen staan naast elkaar op hetzelfde canvas. Een <strong>referentiepunt</strong> vertelt de 3D-server hoe ze op elkaar passen: koppel op elke verdieping <strong>dezelfde hoek van het gebouw</strong>, bijvoorbeeld steeds de hoek linksvoor.</p><ol><li>Tik bij de verdieping op <strong>Koppel</strong>.</li><li>Tik op het canvas de hoek aan. De sidebar blijft open, zodat je meteen de volgende verdieping kunt koppelen.</li></ol><p>Met het oogje toon je de gekoppelde hoeken op het canvas. Een verdieping met een hoogte maar zonder referentiepunt wordt in 3D overgeslagen.</p><div class="tip custom-block"><p class="custom-block-title">Geen gemeenschappelijke hoek?</p><p>Ligt een verdieping versprongen, zoals een kelder onder een deel van de woning? Teken vanaf een hoek van die verdieping een <a href="./muren.html#hulplijn">hulplijn</a> naar het punt dat recht onder of boven de gekozen hoek ligt, en koppel het losse eindpunt van die hulplijn.</p></div><h2 id="isolatie" tabindex="-1">Isolatie <a class="header-anchor" href="#isolatie" aria-label="Permalink to &quot;Isolatie&quot;">​</a></h2><p>De lijst met afwijkende isolaties van deze notitie, bijvoorbeeld <em>Linkergevel 5cm steenwol</em>. Je kent ze toe aan een <a href="./muren.html#isolatie">muur</a>, een <a href="./muren.html#isolatie-van-het-dak">hellend dak</a>, een <a href="./vlakken.html#plat-dak">plat dak</a> of een <a href="./vlakken.html#vloerbegrenzing">vloer</a>. Hier kun je ze ook toevoegen of verwijderen. Een verwijderde isolatie wordt overal weer <em>Standaard</em>.</p>',9))])}const j=d(p,[["render",h]]);export{f as __pageData,j as default};
